 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_22", "type": "likert", "question": "I am able to consciously focus on my body as a whole.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_23", "type": "likert", "question": "I notice how my body changes when I am angry.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}]}, {"id": "maia_p4", "components": [{"id": "maia_24", "type": "likert", "question": "When something is wrong in my life I can feel it in my body.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_25", "type": "likert", "question": "I notice that my body feels different after a peaceful experience.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_26", "type": "likert", "question": "I notice that my breathing becomes free and easy when I feel comfortable.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_27", "type": "likert", "question": "I notice how my body changes when I feel happy / joyful.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, 