lore how my body feels.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_34", "type": "likert", "question": "I listen to my body to inform me about what to do.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_35", "type": "likert", "question": "I am at home in my body.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_36", "type": "likert", "question": "I feel my body is a safe place.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_37", "type": "likert", "question": "I trust my body sensations.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}]}]}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-phq4', 'Over the last two weeks', '{"slug": "sf2-phq4", "name": "Over the last two weeks", "questionnaire_type": "composable", "instructions": "Over the last two weeks, how often have you been bothered by the following problems?", "pages": [{"id": "phq4_p1", "components": [{"id": "phq4_1", "type": "likert", "question": "Feeling nervous, anxious, or on edge", "scale": [{"value": 0, "label": "Not at all"}, {"value": 1, "label": "Several days"}, {"value": 2, "label": "More than half the days"}, {"value": 3, "label": "Nearly every day"}], "required": true, "allow_pna": true}, {"id": "phq4_2", "type": "likert", "question": "Not being able to stop or control worrying", "scale": [{"value": 0, "label": "Not at all"}, {"value": 1, "label": "Several days"}, {"value": 2, "label": "More than half the days"}, {"value": 3, "label": "Nearly every day"}], "required": true, "allow_pna": true}, {"id": "phq4_3", "type": "likert", "question": "Feeling down, depressed, or hopeless", "scale": [{"value": 0, "label": "Not at all"}, {"value": 1, "label": "Several days"}, {"value": 2, "label": "More than half the days"}, {"value": 3, "label": "Nearly every day"}], "required": true, "allow_pna": true}, {"id": "phq4_4", "type": "likert", "question": "Little interest or pleasure in doing things", "scale": [{"value": 0, "label": "Not at all"}, {"value": 1, "label": "Several days"}, {"value": 2, "label": "More than half the days"}, {"value": 3, "label": "Nearly every day"}], "required": true, "allow_pna": true}]}]}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-bidr16', 'About yourself', '{"slug": "sf2-bidr16", "name": "About yourself", "questionnaire_type": "composable", "instructions": "Using the scale below, please indicate how much you agree with each statement. (1 = Not True, 4 = Somewhat True, 7 = Very True)", "pages": [{"id": "bidr_p1", "components": [{"id": "bidr_01", "type": "likert", "question": "I have not always been honest with myself.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_02", "type": "likert", "question": "I always know why I like things.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_03", "type": "likert", "question": "It’s hard for me to shut off a disturbing thought.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_04", "type": "likert", "question": "I never regret my decisions.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_05", "type": "likert", "question": "I sometimes lose out on things because I can’t make up my mind soon enough.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_06", "type": "likert", "question": "I am a completely rational person.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_07", "type": "likert", "question": "I am very confident of my judgments.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_08", "type": "likert", "question": "I have sometimes doubted my ability as a lover.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}]}, {"id": "bidr_p2", "components": [{"id": "bidr_09", "type": "likert", "question": "I sometimes tell lies if I have to.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_10", "type": "likert", "question": "I never cover up my mistakes.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_11", "type": "likert", "question": "There have been occasions when I have taken advantage of someone.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_12", "type": "likert", "question": "I sometimes try to get even rather than forgive and forget.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_13", "type": "likert", "question": "I have said something bad about a friend behind his or her back.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_14", "type": "likert", "question": "When I hear people talking privately, I avoid listening.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_15", "type": "likert", "question": "I never take things that don’t belong to me.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}, {"id": "bidr_16", "type": "likert", "question": "I don’t gossip about other people’s business.", "scale": [{"value": 1, "label": "1 Not true"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Somewhat true"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Very true"}], "required": true, "allow_pna": true}]}]}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-ius12', 'Uncertainty', '{"slug": "sf2-ius12", "name": "Uncertainty", "questionnaire_type": "composable", "instructions": "Please select the number that best corresponds to how much you agree with each item.", "pages": [{"id": "ius_p1", "components": [{"id": "ius12_01", "type": "likert", "question": "Unforeseen events upset me greatly.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_02", "type": "likert", "question": "It frustrates me not having all the information I need.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_03", "type": "likert", "question": "Uncertainty keeps me from living a full life.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_04", "type": "likert", "question": "One should always look ahead so as to avoid surprises.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_05", "type": "likert", "question": "A small unforeseen event can spoil everything, even with the best of planning.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_06", "type": "likert", "question": "When it’s time to act, uncertainty paralyses me.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}]}, {"id": "ius_p2", "components": [{"id": "ius12_07", "type": "likert", "question": "When I am uncertain I can’t function very well.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_08", "type": "likert", "question": "I always want to know what the future has in store for me.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_09", "type": "likert", "question": "I can’t stand being taken by surprise.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_10", "type": "likert", "question": "The smallest doubt can stop me from acting.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_11", "type": "likert", "question": "I should be able to organize everything in advance.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ius12_12", "type": "likert", "question": "I must get away from all uncertain situations.", "scale": [{"value": 1, "label": "Not at all characteristic of me"}, {"value": 2, "label": "A little characteristic of me"}, {"value": 3, "label": "Somewhat characteristic of me"}, {"value": 4, "label": "Very characteristic of me"}, {"value": 5, "label": "Entirely characteristic of me"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "sum", "note": "Carleton, Norton & Asmundson (2007). Lab-form order. Total 12-60.", "subscales": [{"name": "Prospective", "item_ids": ["ius12_01", "ius12_02", "ius12_04", "ius12_05", "ius12_08", "ius12_09", "ius12_11"]}, {"name": "Inhibitory", "item_ids": ["ius12_03", "ius12_06", "ius12_07", "ius12_10", "ius12_12"]}]}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-sbi-moment', 'Enjoying good times', '{"slug": "sf2-sbi-moment", "name": "Enjoying good times", "questionnaire_type": "composable", "instructions": "For each statement listed below, please select the one number that best indicates how true the particular statement is for you. There are no right or wrong answers. Please be as honest as you can.", "pages": [{"id": "sbi_p1", "components": [{"id": "sbi_02", "type": "likert", "question": "It’s hard for me to hang onto a good feeling for very long.", "scale": [{"value": 1, "label": "1 Strongly disagree"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sbi_05", "type": "likert", "question": "I know how to make the most of a good time.", "scale": [{"value": 1, "label": "1 Strongly disagree"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sbi_08", "type": "likert", "question": "When it comes to enjoying myself, I’m my own “worst enemy.”", "scale": [{"value": 1, "label": "1 Strongly disagree"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sbi_11", "type": "likert", "question": "When something good happens, I can make my enjoyment of it last longer by thinking or doing certain things.", "scale": [{"value": 1, "label": "1 Strongly disagree"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sbi_14", "type": "likert", "question": "I can’t seem to capture the joy of happy moments.", "scale": [{"value": 1, "label": "1 Strongly disagree"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sbi_17", "type": "likert", "question": "I feel fully able to appreciate good things that happen to me.", "scale": [{"value": 1, "label": "1 Strongly disagree"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sbi_20", "type": "likert", "question": "I don’t enjoy things as much as I should.", "scale": [{"value": 1, "label": "1 Strongly disagree"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sbi_23", "type": "likert", "question": "It’s easy for me to enjoy myself when I want to.", "scale": [{"value": 1, "label": "1 Strongly disagree"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Strongly agree"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "mean", "note": "Bryant (2003); Savoring the Moment subscale (SBI items 2, 5, 8, 11, 14, 17, 20, 23).", "reverse_items": ["sbi_02", "sbi_08", "sbi_14", "sbi_20"]}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-bfi2-om', 'Characteristics', '{"slug": "sf2-bfi2-om", "name": "Characteristics", "questionnaire_type": "composable", "instructions": "Here are a number of characteristics that may or may not apply to you. For example, do you agree that you are someone who likes to spend time with others? Please select a number for each statement to indicate the extent to which you agree or disagree with that statement.", "pages": [{"id": "bfi_p1", "components": [{"id": "bfi2_05", "type": "likert", "question": "I am someone who… has few artistic interests.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_10", "type": "likert", "question": "I am someone who… is curious about many different things.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_15", "type": "likert", "question": "I am someone who… is inventive, finds clever ways to do things.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_20", "type": "likert", "question": "I am someone who… is fascinated by art, music, or literature.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_25", "type": "likert", "question": "I am someone who… avoids intellectual, philosophical discussions.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_30", "type": "likert", "question": "I am someone who… has little creativity.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_35", "type": "likert", "question": "I am someone who… values art and beauty.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}]}, {"id": "bfi_p2", "components": [{"id": "bfi2_attn_check", "type": "likert", "question": "To show that you are reading each statement, please select \"Agree a little\" for this one.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true}, {"id": "bfi2_40", "type": "likert", "question": "I am someone who… is complex, a deep thinker.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_45", "type": "likert", "question": "I am someone who… has difficulty imagining things.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_50", "type": "likert", "question": "I am someone who… thinks poetry and plays are boring.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_55", "type": "likert", "question": "I am someone who… has little interest in abstract ideas.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}, {"id": "bfi2_60", "type": "likert", "question": "I am someone who… is original, comes up with new ideas.", "scale": [{"value": 1, "label": "Disagree strongly"}, {"value": 2, "label": "Disagree a little"}, {"value": 3, "label": "Neutral; no opinion"}, {"value": 4, "label": "Agree a little"}, {"value": 5, "label": "Agree strongly"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "mean", "note": "Soto & John (2017), Open-Mindedness domain (BFI-2 items).", "reverse_items": ["bfi2_05", "bfi2_25", "bfi2_30", "bfi2_45", "bfi2_50", "bfi2_55"], "subscales": [{"name": "Aesthetic Sensitivity", "item_ids": ["bfi2_05", "bfi2_20", "bfi2_35", "bfi2_50"]}, {"name": "Intellectual Curiosity", "item_ids": ["bfi2_10", "bfi2_25", "bfi2_40", "bfi2_55"]}, {"name": "Creative Imagination", "item_ids": ["bfi2_15", "bfi2_30", "bfi2_45", "bfi2_60"]}]}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-eq-decentering', 'Your experiences', '{"slug": "sf2-eq-decentering", "name": "Your experiences", "questionnaire_type": "composable", "instructions": "For each statement below, please select the number that best describes your general experiences using a scale from 1 to 5, where 1 = Never and 5 = All the time.", "pages": [{"id": "eq_p1", "components": [{"id": "eq_03", "type": "likert", "question": "I am better able to accept myself as I am.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}, {"id": "eq_15", "type": "likert", "question": "I can observe unpleasant feelings without being drawn into them.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}, {"id": "eq_09", "type": "likert", "question": "I notice that I don’t take difficulties so personally.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}, {"id": "eq_14", "type": "likert", "question": "I can treat myself kindly.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}, {"id": "eq_10", "type": "likert", "question": "I can separate myself from my thoughts and feelings.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}, {"id": "eq_16", "type": "likert", "question": "I have the sense that I am fully aware of what is going on around me and inside me.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}]}, {"id": "eq_p2", "components": [{"id": "eq_06", "type": "likert", "question": "I can slow my thinking at times of stress.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}, {"id": "eq_17", "type": "likert", "question": "I can actually see that I am not my thoughts.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}, {"id": "eq_18", "type": "likert", "question": "I am consciously aware of a sense of my body as a whole.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}, {"id": "eq_12", "type": "likert", "question": "I can take time to respond to difficulties.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}, {"id": "eq_20", "type": "likert", "question": "I view things from a wider perspective.", "scale": [{"value": 1, "label": "1 Never"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 All the time"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "sum", "note": "Fresco et al. (2007) Decentering, 11 items (EQ numbers in ids), 11-55."}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-pss4', 'The last month', '{"slug": "sf2-pss4", "name": "The last month", "questionnaire_type": "composable", "instructions": "The questions in this scale ask you about your feelings and thoughts during the last month. In each case, please indicate how often you felt or thought a certain way.", "pages": [{"id": "pss_p1", "components": [{"id": "pss4_1", "type": "likert", "question": "In the last month, how often have you felt that you were unable to control the important things in your life?", "scale": [{"value": 0, "label": "Never"}, {"value": 1, "label": "Almost never"}, {"value": 2, "label": "Sometimes"}, {"value": 3, "label": "Fairly often"}, {"value": 4, "label": "Very often"}], "required": true, "allow_pna": true}, {"id": "pss4_2", "type": "likert", "question": "In the last month, how often have you felt confident about your ability to handle your personal problems?", "scale": [{"value": 0, "label": "Never"}, {"value": 1, "label": "Almost never"}, {"value": 2, "label": "Sometimes"}, {"value": 3, "label": "Fairly often"}, {"value": 4, "label": "Very often"}], "required": true, "allow_pna": true}, {"id": "pss4_3", "type": "likert", "question": "In the last month, how often have you felt that things were going your way?", "scale": [{"value": 0, "label": "Never"}, {"value": 1, "label": "Almost never"}, {"value": 2, "label": "Sometimes"}, {"value": 3, "label": "Fairly often"}, {"value": 4, "label": "Very often"}], "required": true, "allow_pna": true}, {"id": "pss4_4", "type": "likert", "question": "In the last month, how often have you felt difficulties were piling up so high that you could not overcome them?", "scale": [{"value": 0, "label": "Never"}, {"value": 1, "label": "Almost never"}, {"value": 2, "label": "Sometimes"}, {"value": 3, "label": "Fairly often"}, {"value": 4, "label": "Very often"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "sum", "note": "Cohen et al. (1983); items 2 and 3 reverse-coded; 0-16. Licence via Mapi ePROVIDE.", "reverse_items": ["pss4_2", "pss4_3"]}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-past-week', 'Your past week', '{"slug": "sf2-past-week", "name": "Your past week", "questionnaire_type": "composable", "instructions": "A few questions about the past 7 days.", "pages": [{"id": "crit_p1", "components": [{"id": "crit_pause_days", "type": "multiple_choice", "question": "In the past 7 days, on how many days did you deliberately pause to take in your surroundings through your senses?", "options": [{"id": "d0", "label": "0 days", "value": 0}, {"id": "d1", "label": "1 day", "value": 1}, {"id": "d2", "label": "2 days", "value": 2}, {"id": "d3", "label": "3 days", "value": 3}, {"id": "d4", "label": "4 days", "value": 4}, {"id": "d5", "label": "5 days", "value": 5}, {"id": "d6", "label": "6 days", "value": 6}, {"id": "d7", "label": "7 days", "value": 7}], "required": true, "allow_pna": true}, {"id": "crit_notice_first", "type": "multiple_choice", "question": "In the past 7 days, when something unexpected happened, how often were you able to simply notice it before reacting?", "options": [{"id": "never", "label": "Never", "value": 1}, {"id": "rarely", "label": "Rarely", "value": 2}, {"id": "sometimes", "label": "Sometimes", "value": 3}, {"id": "often", "label": "Often", "value": 4}, {"id": "almost_always", "label": "Almost always", "value": 5}, {"id": "nothing_unexpected", "label": "Nothing unexpected happened", "value": "nothing_unexpected"}], "required": true, "allow_pna": true}, {"id": "crit_outdoors", "type": "multiple_choice", "question": "In the past 7 days, about how much time in total did you spend outdoors not doing anything in particular?", "options": [{"id": "none", "label": "None", "value": 0}, {"id": "lt30", "label": "Less than 30 minutes", "value": 1}, {"id": "30_120", "label": "30 minutes to 2 hours", "value": 2}, {"id": "2_5h", "label": "2 to 5 hours", "value": 3}, {"id": "gt5h", "label": "More than 5 hours", "value": 4}], "required": true, "allow_pna": true}]}]}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-sfs-candidates', 'A few more statements', '{"slug": "sf2-sfs-candidates", "name": "A few more statements", "questionnaire_type": "composable", "instructions": "A few more statements about how you pay attention. In general, how much do you agree with each statement? There are no right or wrong answers.", "pages": [{"id": "sfc_p1", "components": [{"id": "sfc_21", "type": "likert", "question": "I can move into the sensing mode even in a stressful or demanding moment", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_24", "type": "likert", "question": "Time in the sensing mode leaves me with a sense of awe or wonder", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_9", "type": "likert", "question": "I usually realize I was in the doing mode only long afterwards", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_16", "type": "likert", "question": "When I am bored, I search my senses for something interesting", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_4", "type": "likert", "question": "When I have free time, I would rather fill it than spend it just sensing", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_23", "type": "likert", "question": "I can tell when a moment calls for the doing mode and when it calls for the sensing mode", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_25", "type": "likert", "question": "I welcome surprise when I am in the sensing mode, rather than trying to predict or control what happens", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_14", "type": "likert", "question": "When I notice something, I have trouble just letting it be", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sfc_p2", "components": [{"id": "sfc_7", "type": "likert", "question": "I can tell which mode I am in while it is happening", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_13", "type": "likert", "question": "After I name a sensation, one thought quickly leads to another", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_3", "type": "likert", "question": "To me, sensing and doing are two names for the same thing", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_5", "type": "likert", "question": "I can feel at ease without knowing what comes next", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_18", "type": "likert", "question": "When I feel too busy, I look for something to take in through my senses", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_12", "type": "likert", "question": "When I notice something, I start explaining it to myself straight away", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_20", "type": "likert", "question": "There is not much left to discover in my everyday surroundings", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_22", "type": "likert", "question": "The sensing mode feels close at hand to me, wherever I am", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sfc_p3", "components": [{"id": "sfc_2", "type": "likert", "question": "My attention works the same way whether I am stressed or relaxed", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_17", "type": "likert", "question": "In familiar places, I look for something I have not noticed before", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_8", "type": "likert", "question": "I notice the moment my attention shifts from sensing to doing", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_10", "type": "likert", "question": "I can notice that something feels unpleasant without trying to change it", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_15", "type": "likert", "question": "Time spent just taking things in feels like time wasted", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_11", "type": "likert", "question": "Once I have named what I notice, I am happy to leave it there", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_19", "type": "likert", "question": "I wait for something interesting to come along rather than looking for it", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfc_6", "type": "likert", "question": "I am content to notice something without working out what it means", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}], "interleave": {"items": ["sfc_2", "sfc_3", "sfc_7", "sfc_8", "sfc_9", "sfc_5", "sfc_6", "sfc_10", "sfc_11", "sfc_12", "sfc_13", "sfc_14", "sfc_4", "sfc_15", "sfc_16", "sfc_17", "sfc_18", "sfc_19", "sfc_20", "sfc_21", "sfc_22", "sfc_23", "sfc_24", "sfc_25"], "page_sizes": [8, 8, 8], "clusters": {"understanding": ["sfc_2", "sfc_3", "sfc_7", "sfc_8", "sfc_9"], "letting_be": ["sfc_5", "sfc_6", "sfc_10", "sfc_11", "sfc_12", "sfc_13", "sfc_14"], "valuing": ["sfc_4", "sfc_15", "sfc_24", "sfc_25"], "forage": ["sfc_16", "sfc_17", "sfc_18", "sfc_19", "sfc_20"], "access": ["sfc_21", "sfc_22", "sfc_23"]}, "cluster_min_gap": 2, "cluster_max_per_page": 3, "groups": [{"items": ["sfc_2", "sfc_3", "sfc_9", "sfc_12", "sfc_13", "sfc_14", "sfc_4", "sfc_15", "sfc_19", "sfc_20"], "min_gap": 1, "max_per_page": 4, "min_per_page": 3, "avoid_positions": [1], "max_run_outside": 4}], "apart_pages": [["sfc_8", "sfc_9"], ["sfc_11", "sfc_12"], ["sfc_4", "sfc_15"], ["sfc_12", "sfc_14"], ["sfc_17", "sfc_20"], ["sfc_16", "sfc_19"], ["sfc_7", "sfc_23"]]}, "candidates": [{"id": "sfc_2", "factor": "Understanding the modes", "reverse_keyed": true}, {"id": "sfc_3", "factor": "Understanding the modes", "reverse_keyed": true}, {"id": "sfc_7", "factor": "Understanding the modes", "reverse_keyed": false}, {"id": "sfc_8", "factor": "Understanding the modes", "reverse_keyed": false}, {"id": "sfc_9", "factor": "Understanding the modes", "reverse_keyed": true}, {"id": "sfc_5", "factor": "Letting be", "reverse_keyed": false}, {"id": "sfc_6", "factor": "Letting be", "reverse_keyed": false}, {"id": "sfc_10", "factor": "Letting be", "reverse_keyed": false}, {"id": "sfc_11", "factor": "Letting be", "reverse_keyed": false}, {"id": "sfc_12", "factor": "Letting be", "reverse_keyed": true}, {"id": "sfc_13", "factor": "Letting be", "reverse_keyed": true}, {"id": "sfc_14", "factor": "Letting be", "reverse_keyed": true}, {"id": "sfc_4", "factor": "Valuing and savouring", "reverse